CREATE TABLE am_categories (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, name VARCHAR(160) NOT NULL UNIQUE, prefix VARCHAR(12) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE, requires_serial BOOLEAN NOT NULL DEFAULT FALSE, tracking ENUM('INDIVIDUAL','QUANTITY','CONFIGURABLE') NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME(3) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE am_sequences (category_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, next_number BIGINT UNSIGNED NOT NULL DEFAULT 1, FOREIGN KEY(category_id) REFERENCES am_categories(id), CHECK(next_number > 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE am_locations (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, name VARCHAR(160) NOT NULL, kind ENUM('WAREHOUSE','LOCATION') NOT NULL, parent_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, department_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE KEY(name,kind), FOREIGN KEY(parent_id) REFERENCES am_locations(id), FOREIGN KEY(department_id) REFERENCES departments(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE am_workstations (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, name VARCHAR(160) NOT NULL UNIQUE, location_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, department_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, employee_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, version INT UNSIGNED NOT NULL DEFAULT 0, FOREIGN KEY(location_id) REFERENCES am_locations(id), FOREIGN KEY(department_id) REFERENCES departments(id), FOREIGN KEY(employee_id) REFERENCES employee_directory(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE am_assets (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, asset_tag VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE, category_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, brand VARCHAR(160) NOT NULL DEFAULT '', model VARCHAR(160) NOT NULL DEFAULT '', serial_number VARCHAR(160) NULL, serial_key VARCHAR(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL UNIQUE, technical_condition ENUM('GOOD','FAULTY','UNDER_INSPECTION','UNREPAIRABLE') NOT NULL, operational_status ENUM('IN_USE','AVAILABLE','RESERVED','IN_MAINTENANCE','RETIRED') NOT NULL, location_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, department_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, custodian_type ENUM('employee','department','none') NOT NULL DEFAULT 'none', employee_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, workstation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, received_date DATE NULL, supplier VARCHAR(160) NOT NULL DEFAULT '', notes TEXT NOT NULL, version INT UNSIGNED NOT NULL DEFAULT 0, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, FOREIGN KEY(category_id) REFERENCES am_categories(id), FOREIGN KEY(location_id) REFERENCES am_locations(id), FOREIGN KEY(department_id) REFERENCES departments(id), FOREIGN KEY(employee_id) REFERENCES employee_directory(id), FOREIGN KEY(workstation_id) REFERENCES am_workstations(id), CHECK((custodian_type='employee' AND employee_id IS NOT NULL AND department_id IS NOT NULL) OR (custodian_type='department' AND employee_id IS NULL AND department_id IS NOT NULL) OR (custodian_type='none' AND employee_id IS NULL)), INDEX(operational_status,technical_condition,location_id), INDEX(department_id,category_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE am_items (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, category_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, name VARCHAR(160) NOT NULL, brand VARCHAR(160) NOT NULL DEFAULT '', model VARCHAR(160) NOT NULL DEFAULT '', minimum_stock INT UNSIGNED NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(category_id) REFERENCES am_categories(id), UNIQUE KEY(category_id,name,brand,model)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE am_balances (item_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, location_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, technical_condition ENUM('GOOD','FAULTY','UNDER_INSPECTION','UNREPAIRABLE') NOT NULL, quantity INT UNSIGNED NOT NULL DEFAULT 0, reserved INT UNSIGNED NOT NULL DEFAULT 0, PRIMARY KEY(item_id,location_id,technical_condition), FOREIGN KEY(item_id) REFERENCES am_items(id), FOREIGN KEY(location_id) REFERENCES am_locations(id), CHECK(quantity>=reserved)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE am_operations (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, actor_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, request_key VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, fingerprint CHAR(64) CHARACTER SET ascii NOT NULL, response JSON NULL, created_at DATETIME(3) NOT NULL, UNIQUE KEY(actor_id,request_key), FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE am_replacements (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, old_asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, new_asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, reason TEXT NOT NULL, ticket_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, actor_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, created_at DATETIME(3) NOT NULL, FOREIGN KEY(old_asset_id) REFERENCES am_assets(id), FOREIGN KEY(new_asset_id) REFERENCES am_assets(id), FOREIGN KEY(ticket_id) REFERENCES tickets(id), FOREIGN KEY(actor_id) REFERENCES users(id), CHECK(old_asset_id<>new_asset_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE am_movements (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, type VARCHAR(40) NOT NULL, asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, item_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, quantity INT UNSIGNED NOT NULL DEFAULT 1, source_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, destination_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, previous_state JSON NOT NULL, new_state JSON NOT NULL, actor_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, reason TEXT NOT NULL, ticket_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, replacement_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, created_at DATETIME(3) NOT NULL, FOREIGN KEY(asset_id) REFERENCES am_assets(id), FOREIGN KEY(item_id) REFERENCES am_items(id), FOREIGN KEY(source_id) REFERENCES am_locations(id), FOREIGN KEY(destination_id) REFERENCES am_locations(id), FOREIGN KEY(actor_id) REFERENCES users(id), FOREIGN KEY(ticket_id) REFERENCES tickets(id), FOREIGN KEY(replacement_id) REFERENCES am_replacements(id), CHECK((asset_id IS NULL)<>(item_id IS NULL)), CHECK(quantity>0), INDEX(asset_id,created_at), INDEX(item_id,created_at), INDEX(type,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE am_stock_transactions (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, movement_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE, item_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, location_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, destination_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, technical_condition VARCHAR(24) NOT NULL, quantity_delta INT NOT NULL, reserved_delta INT NOT NULL, result_quantity INT UNSIGNED NOT NULL, result_reserved INT UNSIGNED NOT NULL, FOREIGN KEY(movement_id) REFERENCES am_movements(id), FOREIGN KEY(item_id) REFERENCES am_items(id), FOREIGN KEY(location_id) REFERENCES am_locations(id), FOREIGN KEY(destination_id) REFERENCES am_locations(id), CHECK(result_quantity>=result_reserved)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE am_custody (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, type ENUM('employee','department') NOT NULL, employee_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, department_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, location_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, issued_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, issued_at DATETIME(3) NOT NULL, ended_at DATETIME(3) NULL, acknowledgement ENUM('PENDING','ACKNOWLEDGED') NOT NULL DEFAULT 'PENDING', received_by VARCHAR(160) NULL, acknowledged_at DATETIME(3) NULL, acknowledged_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, receipt_attachment_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, movement_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, notes TEXT NOT NULL, active_asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (CASE WHEN ended_at IS NULL THEN asset_id ELSE NULL END) STORED UNIQUE, FOREIGN KEY(asset_id) REFERENCES am_assets(id), FOREIGN KEY(employee_id) REFERENCES employee_directory(id), FOREIGN KEY(department_id) REFERENCES departments(id), FOREIGN KEY(location_id) REFERENCES am_locations(id), FOREIGN KEY(issued_by) REFERENCES users(id), FOREIGN KEY(acknowledged_by) REFERENCES users(id), FOREIGN KEY(movement_id) REFERENCES am_movements(id), CHECK((type='employee' AND employee_id IS NOT NULL) OR (type='department' AND employee_id IS NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE am_maintenance (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, issue_description TEXT NOT NULL, engineer_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, status ENUM('OPEN','CLOSED') NOT NULL DEFAULT 'OPEN', action_taken TEXT NOT NULL, outcome ENUM('REPAIRED','AWAITING_PART','UNDER_INSPECTION','BEYOND_ECONOMICAL_REPAIR','UNREPAIRABLE') NULL, provider VARCHAR(160) NOT NULL DEFAULT '', cost DECIMAL(14,2) NULL, ticket_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, notes TEXT NOT NULL, created_at DATETIME(3) NOT NULL, closed_at DATETIME(3) NULL, active_asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (CASE WHEN status='OPEN' THEN asset_id ELSE NULL END) STORED UNIQUE, FOREIGN KEY(asset_id) REFERENCES am_assets(id), FOREIGN KEY(engineer_id) REFERENCES users(id), FOREIGN KEY(ticket_id) REFERENCES tickets(id), CHECK(cost IS NULL OR cost>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE am_inventory_sessions (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, name VARCHAR(160) NOT NULL, type ENUM('INITIAL','PERIODIC') NOT NULL, status ENUM('DRAFT','REVIEW','APPROVED','FINALIZED') NOT NULL DEFAULT 'DRAFT', location_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, department_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, category_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, approved_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, created_at DATETIME(3) NOT NULL, finalized_at DATETIME(3) NULL, FOREIGN KEY(location_id) REFERENCES am_locations(id), FOREIGN KEY(department_id) REFERENCES departments(id), FOREIGN KEY(category_id) REFERENCES am_categories(id), FOREIGN KEY(created_by) REFERENCES users(id), FOREIGN KEY(approved_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE am_inventory_entries (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, session_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, item_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, location_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, technical_condition VARCHAR(24) NOT NULL, expected_quantity INT UNSIGNED NOT NULL, counted_quantity INT UNSIGNED NULL, expected_version INT UNSIGNED NULL, observed_condition VARCHAR(24) NULL, observed_location_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, discrepancy ENUM('NONE','MISSING','UNEXPECTED','QUANTITY','CONDITION','LOCATION') NOT NULL DEFAULT 'NONE', decision ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING', notes TEXT NOT NULL, counted_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, applied_movement_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, UNIQUE KEY(session_id,asset_id), UNIQUE KEY(session_id,item_id,location_id,technical_condition), FOREIGN KEY(session_id) REFERENCES am_inventory_sessions(id), FOREIGN KEY(asset_id) REFERENCES am_assets(id), FOREIGN KEY(item_id) REFERENCES am_items(id), FOREIGN KEY(location_id) REFERENCES am_locations(id), FOREIGN KEY(observed_location_id) REFERENCES am_locations(id), FOREIGN KEY(counted_by) REFERENCES users(id), FOREIGN KEY(applied_movement_id) REFERENCES am_movements(id), CHECK((asset_id IS NULL)<>(item_id IS NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE am_attachments (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, maintenance_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, file_name VARCHAR(160) NOT NULL, media_type VARCHAR(80) NOT NULL, byte_length INT UNSIGNED NOT NULL, sha256 CHAR(64) CHARACTER SET ascii NOT NULL, content MEDIUMBLOB NOT NULL, uploaded_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, created_at DATETIME(3) NOT NULL, FOREIGN KEY(asset_id) REFERENCES am_assets(id), FOREIGN KEY(maintenance_id) REFERENCES am_maintenance(id), FOREIGN KEY(uploaded_by) REFERENCES users(id), CHECK(byte_length BETWEEN 1 AND 5242880)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE am_audit (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, entity_type VARCHAR(40) NOT NULL, entity_id VARCHAR(40) CHARACTER SET ascii NOT NULL, action VARCHAR(40) NOT NULL, actor_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, before_data JSON NULL, after_data JSON NOT NULL, created_at DATETIME(3) NOT NULL, FOREIGN KEY(actor_id) REFERENCES users(id), INDEX(entity_type,entity_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE am_workstation_history (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, workstation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, action ENUM('ATTACH','DETACH','TRANSFER','REPLACE') NOT NULL, actor_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, created_at DATETIME(3) NOT NULL, FOREIGN KEY(workstation_id) REFERENCES am_workstations(id), FOREIGN KEY(asset_id) REFERENCES am_assets(id), FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE am_ticket_links (ticket_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, actor_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, created_at DATETIME(3) NOT NULL, PRIMARY KEY(ticket_id,asset_id), FOREIGN KEY(ticket_id) REFERENCES tickets(id), FOREIGN KEY(asset_id) REFERENCES am_assets(id), FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE am_legacy_mappings (legacy_asset_id VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL UNIQUE, item_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, actor_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, created_at DATETIME(3) NOT NULL, FOREIGN KEY(legacy_asset_id) REFERENCES assets(asset_id), FOREIGN KEY(asset_id) REFERENCES am_assets(id), FOREIGN KEY(item_id) REFERENCES am_items(id), FOREIGN KEY(actor_id) REFERENCES users(id), CHECK((asset_id IS NULL)<>(item_id IS NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE notification_events DROP FOREIGN KEY notification_events_history_fk, MODIFY ticket_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, MODIFY type ENUM('new_ticket','ticket_assignment','ticket_resolved','ticket_reopened','asset_event') NOT NULL, ADD resource_type VARCHAR(40) NULL, ADD resource_id VARCHAR(40) CHARACTER SET ascii NULL;

