CREATE TABLE am_initial_rows (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, session_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, source_key VARCHAR(128) NOT NULL, payload JSON NOT NULL, UNIQUE KEY(session_id,source_key), FOREIGN KEY(session_id) REFERENCES am_inventory_sessions(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
